export interface ExpectedPixel {
  x: number;
  y: number;
  expected: [number, number, number];
  tolerance?: number;
}

export type ValidationRule =
  | { type: "functionCall"; name: string; exactArgs?: number; minArgs?: number }
  | { type: "functionExists"; name: string }
  | { type: "canvasSize"; width: number; height: number }
  | { type: "pixelMatch"; x: number; y: number; expected: [number, number, number]; tolerance?: number }
  | { type: "expectedPixels"; points: ExpectedPixel[]; minPassFraction?: number }
  | { type: string; [key: string]: unknown };

export interface ExerciseTask {
  id: string;
  title: string;
  instruction: string;
  validation: ValidationRule[];
  startingCode?: string;
  solution?: string;
}

export interface Exercise {
  id: string;
  title: string;
  module: string;
  description: string;
  instruction: string;
  startingCode?: string;
  solution?: string;
  tasks?: ExerciseTask[];
}

export interface Course {
  slug: string;
  title: string;
  moduleName: string;
  description: string;
  exercises: Exercise[];
}

